-- READ ONLY. Academic Calendar deployed-schema compatibility repair.
-- Continue only when the final visible row is OVERALL | READY.
-- This operator report is one ordinary SELECT result set for phpMyAdmin.

WITH
metadata_checks AS (
    SELECT
      (SELECT COUNT(*) = 1 FROM information_schema.schemata WHERE schema_name='alrowad_uni_rust') AS database_ok,
      (SELECT COUNT(*) = 11 FROM information_schema.tables WHERE table_schema='alrowad_uni_rust' AND table_type='BASE TABLE' AND table_name IN ('academic_years','semesters','users','academic_calendar_event_types','academic_calendar_events','academic_calendar_event_versions','academic_calendar_year_lifecycle_events','system_modules','permissions','roles','role_permissions')) AS required_tables_ok,
      (SELECT COUNT(*) = 4 FROM information_schema.tables WHERE table_schema='alrowad_uni_rust' AND table_type='BASE TABLE' AND engine='InnoDB' AND table_name IN ('academic_calendar_event_types','academic_calendar_events','academic_calendar_event_versions','academic_calendar_year_lifecycle_events')) AS calendar_tables_ok,
      (SELECT COUNT(*) = 17 FROM information_schema.columns WHERE table_schema='alrowad_uni_rust' AND ((table_name='academic_years' AND column_name IN ('academic_year_id','is_current','is_active','calendar_lifecycle_status')) OR (table_name='semesters' AND column_name='semester_code') OR (table_name='academic_calendar_event_types' AND column_name='event_type_code') OR (table_name='system_modules' AND column_name IN ('module_id','module_code')) OR (table_name='permissions' AND column_name IN ('permission_id','module_id','permission_code','is_active')) OR (table_name='roles' AND column_name IN ('role_id','role_code','is_active')) OR (table_name='role_permissions' AND column_name IN ('role_id','permission_id')))) AS data_columns_ok
),
column_checks AS (
    SELECT
      (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema='alrowad_uni_rust' AND ((table_name='academic_calendar_event_types' AND column_name IN ('academic_calendar_event_type_id','event_type_code','name_ar','name_en','event_type_kind','default_is_enforcement','is_active','created_at','updated_at')) OR (table_name='academic_calendar_events' AND column_name IN ('academic_calendar_event_id','academic_year_id','created_by_user_id','created_at','cancelled_by_user_id','cancelled_at','cancellation_reason')) OR (table_name='academic_calendar_event_versions' AND column_name IN ('academic_calendar_event_version_id','academic_calendar_event_id','version_number','replaces_version_id','title','public_notes','starts_at','ends_at','is_enforcement','change_reason','created_by_user_id','created_at','publication_status','published_by_user_id','published_at','superseded_at','published_event_slot')) OR (table_name='academic_calendar_year_lifecycle_events' AND column_name IN ('academic_calendar_year_lifecycle_event_id','academic_year_id','from_status','to_status','actor_user_id','reason','occurred_at')))) AS common_columns,
      (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema='alrowad_uni_rust' AND table_name IN ('academic_calendar_event_types','academic_calendar_events','academic_calendar_event_versions','academic_calendar_year_lifecycle_events')) AS calendar_column_total,
      (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema='alrowad_uni_rust' AND table_name IN ('academic_calendar_event_types','academic_calendar_events','academic_calendar_event_versions','academic_calendar_year_lifecycle_events') AND NOT ((table_name='academic_calendar_event_types' AND column_name IN ('academic_calendar_event_type_id','event_type_code','name_ar','name_en','event_type_kind','default_is_enforcement','is_active','created_at','updated_at')) OR (table_name='academic_calendar_events' AND column_name IN ('academic_calendar_event_id','academic_year_id','semester_id','academic_calendar_event_type_id','created_by_user_id','created_at','cancelled_by_user_id','cancelled_at','cancellation_reason')) OR (table_name='academic_calendar_event_versions' AND column_name IN ('academic_calendar_event_version_id','academic_calendar_event_id','version_number','replaces_version_id','semester_id','academic_calendar_event_type_id','title','public_notes','starts_at','ends_at','is_enforcement','change_reason','created_by_user_id','created_at','publication_status','published_by_user_id','published_at','superseded_at','published_event_slot')) OR (table_name='academic_calendar_year_lifecycle_events' AND column_name IN ('academic_calendar_year_lifecycle_event_id','academic_year_id','from_status','to_status','actor_user_id','reason','occurred_at')))) AS unknown_columns,
      (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema='alrowad_uni_rust' AND table_name='academic_calendar_events' AND column_name IN ('semester_id','academic_calendar_event_type_id')) AS event_context_columns,
      (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema='alrowad_uni_rust' AND table_name='academic_calendar_event_versions' AND column_name IN ('semester_id','academic_calendar_event_type_id')) AS version_context_columns,
      (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema='alrowad_uni_rust' AND data_type='int' AND LOWER(column_type) NOT LIKE '%unsigned%' AND ((table_name='academic_years' AND column_name='academic_year_id') OR (table_name='semesters' AND column_name='semester_id') OR (table_name='users' AND column_name='user_id') OR (table_name='academic_calendar_event_types' AND column_name='academic_calendar_event_type_id') OR (table_name='academic_calendar_events' AND column_name IN ('academic_calendar_event_id','academic_year_id','created_by_user_id','cancelled_by_user_id')) OR (table_name='academic_calendar_event_versions' AND column_name IN ('academic_calendar_event_version_id','academic_calendar_event_id','replaces_version_id','created_by_user_id','published_by_user_id')) OR (table_name='academic_calendar_year_lifecycle_events' AND column_name IN ('academic_calendar_year_lifecycle_event_id','academic_year_id','actor_user_id')))) AS common_signed_keys,
      (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema='alrowad_uni_rust' AND data_type='int' AND LOWER(column_type) NOT LIKE '%unsigned%' AND table_name IN ('academic_calendar_events','academic_calendar_event_versions') AND column_name IN ('semester_id','academic_calendar_event_type_id')) AS context_signed_keys,
      (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema='alrowad_uni_rust' AND data_type='enum' AND ((table_name='academic_years' AND column_name='calendar_lifecycle_status') OR (table_name='academic_calendar_event_types' AND column_name='event_type_kind') OR (table_name='academic_calendar_event_versions' AND column_name='publication_status') OR (table_name='academic_calendar_year_lifecycle_events' AND column_name IN ('from_status','to_status')))) AS state_enum_columns,
      (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema='alrowad_uni_rust' AND data_type='varchar' AND character_maximum_length>=16 AND ((table_name='academic_years' AND column_name='calendar_lifecycle_status') OR (table_name='academic_calendar_event_types' AND column_name='event_type_kind') OR (table_name='academic_calendar_event_versions' AND column_name='publication_status') OR (table_name='academic_calendar_year_lifecycle_events' AND column_name IN ('from_status','to_status')))) AS state_varchar_columns
),
generated_checks AS (
    SELECT
      (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema='alrowad_uni_rust' AND is_generated='ALWAYS' AND (UPPER(extra) LIKE '%PERSISTENT%' OR UPPER(extra) LIKE '%STORED%') AND ((table_name='academic_years' AND column_name='calendar_active_slot' AND generation_expression LIKE '%calendar_lifecycle_status%') OR (table_name='academic_calendar_event_versions' AND column_name='published_event_slot' AND generation_expression LIKE '%publication_status%' AND generation_expression LIKE '%academic_calendar_event_id%'))) AS generated_slots,
      (SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema='alrowad_uni_rust' AND non_unique=0 AND seq_in_index=1 AND ((table_name='academic_years' AND index_name='uq_ay_calendar_active_slot' AND column_name='calendar_active_slot') OR (table_name='academic_calendar_event_versions' AND index_name='uq_acev_published_event_slot' AND column_name='published_event_slot'))) AS generated_unique_indexes
),
check_checks AS (
    SELECT
      (SELECT COUNT(*) FROM information_schema.table_constraints WHERE table_schema='alrowad_uni_rust' AND constraint_type='CHECK' AND ((table_name='academic_years' AND constraint_name='chk_ay_calendar_lifecycle_status') OR (table_name='academic_calendar_event_types' AND constraint_name IN ('chk_acet_kind','chk_acet_flags')) OR (table_name='academic_calendar_events' AND constraint_name='chk_ace_cancellation') OR (table_name='academic_calendar_event_versions' AND constraint_name IN ('chk_acev_version_number','chk_acev_window','chk_acev_enforcement','chk_acev_change_reason','chk_acev_publication')) OR (table_name='academic_calendar_year_lifecycle_events' AND constraint_name IN ('chk_acyle_from_status','chk_acyle_to_status','chk_acyle_reason')))) AS known_check_count,
      (SELECT COUNT(*) FROM information_schema.table_constraints WHERE table_schema='alrowad_uni_rust' AND constraint_type='CHECK' AND table_name IN ('academic_calendar_event_types','academic_calendar_events','academic_calendar_event_versions','academic_calendar_year_lifecycle_events') AND NOT ((table_name='academic_calendar_event_types' AND constraint_name IN ('chk_acet_kind','chk_acet_flags')) OR (table_name='academic_calendar_events' AND constraint_name='chk_ace_cancellation') OR (table_name='academic_calendar_event_versions' AND constraint_name IN ('chk_acev_version_number','chk_acev_window','chk_acev_enforcement','chk_acev_change_reason','chk_acev_publication')) OR (table_name='academic_calendar_year_lifecycle_events' AND constraint_name IN ('chk_acyle_from_status','chk_acyle_to_status','chk_acyle_reason')))) AS unknown_checks
),
foreign_key_checks AS (
    SELECT
      (SELECT COUNT(*) FROM information_schema.key_column_usage WHERE table_schema='alrowad_uni_rust' AND referenced_table_name IS NOT NULL AND table_name IN ('academic_calendar_events','academic_calendar_event_versions') AND column_name IN ('semester_id','academic_calendar_event_type_id') AND constraint_name NOT IN ('fk_ace_semester','fk_ace_event_type','fk_acev_semester','fk_acev_event_type')) AS unknown_context_fks,
      (SELECT COUNT(*) FROM information_schema.key_column_usage k JOIN information_schema.referential_constraints r ON r.constraint_schema=k.constraint_schema AND r.table_name=k.table_name AND r.constraint_name=k.constraint_name WHERE k.table_schema='alrowad_uni_rust' AND k.referenced_table_name IS NOT NULL AND r.delete_rule IN ('RESTRICT','NO ACTION') AND r.update_rule IN ('RESTRICT','NO ACTION') AND ((k.table_name='academic_calendar_events' AND k.constraint_name='fk_ace_year' AND k.column_name='academic_year_id' AND k.referenced_table_name='academic_years' AND k.referenced_column_name='academic_year_id') OR (k.table_name='academic_calendar_events' AND k.constraint_name='fk_ace_created_by' AND k.column_name='created_by_user_id' AND k.referenced_table_name='users' AND k.referenced_column_name='user_id') OR (k.table_name='academic_calendar_events' AND k.constraint_name='fk_ace_cancelled_by' AND k.column_name='cancelled_by_user_id' AND k.referenced_table_name='users' AND k.referenced_column_name='user_id') OR (k.table_name='academic_calendar_event_versions' AND k.constraint_name='fk_acev_event' AND k.column_name='academic_calendar_event_id' AND k.referenced_table_name='academic_calendar_events' AND k.referenced_column_name='academic_calendar_event_id') OR (k.table_name='academic_calendar_event_versions' AND k.constraint_name='fk_acev_replaces' AND k.column_name='replaces_version_id' AND k.referenced_table_name='academic_calendar_event_versions' AND k.referenced_column_name='academic_calendar_event_version_id') OR (k.table_name='academic_calendar_event_versions' AND k.constraint_name='fk_acev_created_by' AND k.column_name='created_by_user_id' AND k.referenced_table_name='users' AND k.referenced_column_name='user_id') OR (k.table_name='academic_calendar_event_versions' AND k.constraint_name='fk_acev_published_by' AND k.column_name='published_by_user_id' AND k.referenced_table_name='users' AND k.referenced_column_name='user_id') OR (k.table_name='academic_calendar_year_lifecycle_events' AND k.constraint_name='fk_acyle_year' AND k.column_name='academic_year_id' AND k.referenced_table_name='academic_years' AND k.referenced_column_name='academic_year_id') OR (k.table_name='academic_calendar_year_lifecycle_events' AND k.constraint_name='fk_acyle_actor' AND k.column_name='actor_user_id' AND k.referenced_table_name='users' AND k.referenced_column_name='user_id'))) AS noncontext_fks,
      (SELECT COUNT(*) FROM information_schema.key_column_usage WHERE table_schema='alrowad_uni_rust' AND referenced_table_name IS NOT NULL AND table_name IN ('academic_calendar_events','academic_calendar_event_versions','academic_calendar_year_lifecycle_events') AND constraint_name NOT IN ('fk_ace_year','fk_ace_semester','fk_ace_event_type','fk_ace_created_by','fk_ace_cancelled_by','fk_acev_event','fk_acev_replaces','fk_acev_semester','fk_acev_event_type','fk_acev_created_by','fk_acev_published_by','fk_acyle_year','fk_acyle_actor')) AS unknown_calendar_fks,
      (SELECT COUNT(*) FROM information_schema.key_column_usage k JOIN information_schema.referential_constraints r ON r.constraint_schema=k.constraint_schema AND r.table_name=k.table_name AND r.constraint_name=k.constraint_name WHERE k.table_schema='alrowad_uni_rust' AND k.table_name='academic_calendar_event_versions' AND r.delete_rule IN ('RESTRICT','NO ACTION') AND r.update_rule IN ('RESTRICT','NO ACTION') AND ((k.constraint_name='fk_acev_semester' AND k.column_name='semester_id' AND k.referenced_table_name='semesters' AND k.referenced_column_name='semester_id') OR (k.constraint_name='fk_acev_event_type' AND k.column_name='academic_calendar_event_type_id' AND k.referenced_table_name='academic_calendar_event_types' AND k.referenced_column_name='academic_calendar_event_type_id'))) AS context_fk_source,
      (SELECT COUNT(*) FROM information_schema.key_column_usage k JOIN information_schema.referential_constraints r ON r.constraint_schema=k.constraint_schema AND r.table_name=k.table_name AND r.constraint_name=k.constraint_name WHERE k.table_schema='alrowad_uni_rust' AND k.table_name='academic_calendar_events' AND r.delete_rule IN ('RESTRICT','NO ACTION') AND r.update_rule IN ('RESTRICT','NO ACTION') AND ((k.constraint_name='fk_ace_semester' AND k.column_name='semester_id' AND k.referenced_table_name='semesters' AND k.referenced_column_name='semester_id') OR (k.constraint_name='fk_ace_event_type' AND k.column_name='academic_calendar_event_type_id' AND k.referenced_table_name='academic_calendar_event_types' AND k.referenced_column_name='academic_calendar_event_type_id'))) AS context_fk_target,
      (SELECT COUNT(*) FROM information_schema.key_column_usage WHERE table_schema='alrowad_uni_rust' AND referenced_table_name IS NOT NULL AND ((table_name='academic_calendar_events' AND constraint_name IN ('fk_ace_semester','fk_ace_event_type')) OR (table_name='academic_calendar_event_versions' AND constraint_name IN ('fk_acev_semester','fk_acev_event_type')))) AS context_fk_total
),
index_checks AS (
    SELECT
      (SELECT COUNT(DISTINCT table_name,index_name) FROM information_schema.statistics WHERE table_schema='alrowad_uni_rust' AND table_name IN ('academic_calendar_event_types','academic_calendar_events','academic_calendar_event_versions','academic_calendar_year_lifecycle_events') AND NOT ((table_name='academic_calendar_event_types' AND index_name IN ('PRIMARY','uq_acet_code','idx_acet_kind_active')) OR (table_name='academic_calendar_events' AND index_name IN ('PRIMARY','idx_ace_year','idx_ace_year_semester','idx_ace_event_type','idx_ace_cancelled_at','idx_ace_created_by','idx_ace_cancelled_by')) OR (table_name='academic_calendar_event_versions' AND index_name IN ('PRIMARY','uq_acev_event_version','uq_acev_published_event_slot','idx_acev_event_status','idx_acev_semester','idx_acev_event_type','idx_acev_publication_window','idx_acev_replaces','idx_acev_created_by','idx_acev_published_by')) OR (table_name='academic_calendar_year_lifecycle_events' AND index_name IN ('PRIMARY','idx_acyle_year_occurred','idx_acyle_to_status','idx_acyle_status_occurred','idx_acyle_actor')))) AS unknown_indexes,
      (SELECT COUNT(DISTINCT table_name,index_name) FROM information_schema.statistics WHERE table_schema='alrowad_uni_rust' AND ((table_name='academic_calendar_event_types' AND index_name='idx_acet_kind_active') OR (table_name='academic_calendar_events' AND index_name='idx_ace_cancelled_at') OR (table_name='academic_calendar_event_versions' AND index_name IN ('idx_acev_event_status','idx_acev_publication_window','idx_acev_replaces')) OR (table_name='academic_calendar_year_lifecycle_events' AND index_name IN ('idx_acyle_year_occurred','idx_acyle_actor')))) AS known_common_index_names,
      (SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema='alrowad_uni_rust' AND seq_in_index=1 AND ((table_name='academic_calendar_event_types' AND index_name='idx_acet_kind_active' AND column_name='event_type_kind') OR (table_name='academic_calendar_events' AND index_name='idx_ace_cancelled_at' AND column_name='cancelled_at') OR (table_name='academic_calendar_event_versions' AND index_name='idx_acev_event_status' AND column_name='academic_calendar_event_id') OR (table_name='academic_calendar_event_versions' AND index_name='idx_acev_publication_window' AND column_name='publication_status') OR (table_name='academic_calendar_event_versions' AND index_name='idx_acev_replaces' AND column_name='replaces_version_id') OR (table_name='academic_calendar_year_lifecycle_events' AND index_name='idx_acyle_year_occurred' AND column_name='academic_year_id') OR (table_name='academic_calendar_year_lifecycle_events' AND index_name='idx_acyle_actor' AND column_name='actor_user_id'))) AS compatible_common_indexes,
      (SELECT COUNT(DISTINCT table_name,index_name) FROM information_schema.statistics WHERE table_schema='alrowad_uni_rust' AND ((table_name='academic_calendar_events' AND index_name IN ('idx_ace_year','idx_ace_year_semester','idx_ace_event_type')) OR (table_name='academic_calendar_event_versions' AND index_name IN ('idx_acev_semester','idx_acev_event_type')) OR (table_name='academic_calendar_year_lifecycle_events' AND index_name IN ('idx_acyle_to_status','idx_acyle_status_occurred')))) AS known_migration_index_names,
      (SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema='alrowad_uni_rust' AND seq_in_index=1 AND ((table_name='academic_calendar_events' AND index_name='idx_ace_year' AND column_name='academic_year_id') OR (table_name='academic_calendar_events' AND index_name='idx_ace_year_semester' AND column_name='academic_year_id') OR (table_name='academic_calendar_events' AND index_name='idx_ace_event_type' AND column_name='academic_calendar_event_type_id') OR (table_name='academic_calendar_event_versions' AND index_name='idx_acev_semester' AND column_name='semester_id') OR (table_name='academic_calendar_event_versions' AND index_name='idx_acev_event_type' AND column_name='academic_calendar_event_type_id') OR (table_name='academic_calendar_year_lifecycle_events' AND index_name='idx_acyle_to_status' AND column_name='to_status') OR (table_name='academic_calendar_year_lifecycle_events' AND index_name='idx_acyle_status_occurred' AND column_name='to_status'))) AS compatible_migration_indexes,
      (SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema='alrowad_uni_rust' AND seq_in_index=1 AND ((table_name='academic_calendar_events' AND index_name='idx_ace_year' AND column_name='academic_year_id') OR (table_name='academic_calendar_event_versions' AND index_name='idx_acev_semester' AND column_name='semester_id') OR (table_name='academic_calendar_event_versions' AND index_name='idx_acev_event_type' AND column_name='academic_calendar_event_type_id') OR (table_name='academic_calendar_year_lifecycle_events' AND index_name='idx_acyle_to_status' AND column_name='to_status'))) AS source_indexes,
      (SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema='alrowad_uni_rust' AND seq_in_index=1 AND ((table_name='academic_calendar_event_types' AND index_name='idx_acet_kind_active' AND column_name='event_type_kind') OR (table_name='academic_calendar_events' AND index_name='idx_ace_year_semester' AND column_name='academic_year_id') OR (table_name='academic_calendar_events' AND index_name='idx_ace_event_type' AND column_name='academic_calendar_event_type_id') OR (table_name='academic_calendar_events' AND index_name='idx_ace_cancelled_at' AND column_name='cancelled_at') OR (table_name='academic_calendar_event_versions' AND index_name='idx_acev_event_status' AND column_name='academic_calendar_event_id') OR (table_name='academic_calendar_event_versions' AND index_name='idx_acev_publication_window' AND column_name='publication_status') OR (table_name='academic_calendar_event_versions' AND index_name='idx_acev_replaces' AND column_name='replaces_version_id') OR (table_name='academic_calendar_year_lifecycle_events' AND index_name='idx_acyle_year_occurred' AND column_name='academic_year_id') OR (table_name='academic_calendar_year_lifecycle_events' AND index_name='idx_acyle_status_occurred' AND column_name='to_status') OR (table_name='academic_calendar_year_lifecycle_events' AND index_name='idx_acyle_actor' AND column_name='actor_user_id'))) AS target_indexes
),
comment_checks AS (
    SELECT (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema='alrowad_uni_rust' AND ((table_name='academic_calendar_event_types' AND table_comment='[academic-calendar-phase1] stable event vocabulary') OR (table_name='academic_calendar_events' AND table_comment='[academic-calendar-phase1] logical university calendar events') OR (table_name='academic_calendar_event_versions' AND table_comment='[academic-calendar-phase1] immutable event content revisions') OR (table_name='academic_calendar_year_lifecycle_events' AND table_comment='[academic-calendar-phase1] append-only academic year lifecycle history'))) AS table_comments
),
data_checks AS (
    SELECT
      (SELECT COUNT(*) FROM `alrowad_uni_rust`.`academic_calendar_events`) AS event_rows,
      (SELECT COUNT(*) FROM `alrowad_uni_rust`.`academic_calendar_event_versions`) AS version_rows,
      (SELECT COUNT(DISTINCT event_type_code) FROM `alrowad_uni_rust`.`academic_calendar_event_types` WHERE event_type_code IN ('admission_registration','course_registration','withdrawal','study_period','exam_preparation','practical_exams','theoretical_exams','grade_appeals','supplementary_exams','university_break','preparation_period','holiday','general_event')) AS seed_codes,
      (SELECT COUNT(*) FROM `alrowad_uni_rust`.`academic_years` WHERE is_current=1 AND is_active=1 AND calendar_lifecycle_status='active') AS current_active,
      (SELECT COUNT(*) FROM `alrowad_uni_rust`.`academic_years` WHERE is_current=1) AS current_count,
      (SELECT COUNT(DISTINCT semester_code) FROM `alrowad_uni_rust`.`semesters` WHERE semester_code IN ('first','second','summer')) AS semester_codes,
      (SELECT COUNT(*) FROM `alrowad_uni_rust`.`permissions` p JOIN `alrowad_uni_rust`.`system_modules` m ON m.module_id=p.module_id WHERE p.permission_code='academic_calendar.manage' AND p.is_active=1 AND m.module_code='vice_presidency') AS permission_ok,
      (SELECT COUNT(*) FROM `alrowad_uni_rust`.`role_permissions` rp JOIN `alrowad_uni_rust`.`permissions` p ON p.permission_id=rp.permission_id JOIN `alrowad_uni_rust`.`roles` r ON r.role_id=rp.role_id WHERE p.permission_code='academic_calendar.manage' AND r.role_code='vice_president_scientific' AND r.is_active=1) AS role_mapping_ok,
      (SELECT COUNT(*) FROM `alrowad_uni_rust`.`role_permissions` rp JOIN `alrowad_uni_rust`.`permissions` p ON p.permission_id=rp.permission_id JOIN `alrowad_uni_rust`.`roles` r ON r.role_id=rp.role_id WHERE p.permission_code='academic_calendar.manage' AND r.role_code<>'vice_president_scientific') AS other_mappings
),
facts AS (
    SELECT * FROM metadata_checks CROSS JOIN column_checks CROSS JOIN generated_checks CROSS JOIN check_checks CROSS JOIN foreign_key_checks CROSS JOIN index_checks CROSS JOIN comment_checks CROSS JOIN data_checks
),
safety AS (
    SELECT facts.*,
      (event_rows=0 AND version_rows=0 AND seed_codes=13 AND current_active=1 AND current_count=1 AND semester_codes=3 AND permission_ok=1 AND role_mapping_ok=1 AND other_mappings=0) AS data_safe,
      (database_ok AND required_tables_ok AND data_columns_ok AND calendar_tables_ok AND common_columns=40 AND unknown_columns=0 AND calendar_column_total BETWEEN 40 AND 44 AND common_signed_keys=16 AND context_signed_keys=(event_context_columns+version_context_columns) AND generated_slots=2 AND generated_unique_indexes=2 AND unknown_checks=0 AND unknown_context_fks=0 AND noncontext_fks=9 AND unknown_calendar_fks=0 AND (context_fk_source+context_fk_target)=context_fk_total AND unknown_indexes=0 AND known_common_index_names=compatible_common_indexes AND known_migration_index_names=compatible_migration_indexes AND (state_enum_columns+state_varchar_columns)=5) AS structure_safe
    FROM facts
),
fingerprints AS (
    SELECT safety.*,
      (structure_safe AND data_safe AND calendar_column_total=42 AND event_context_columns=0 AND version_context_columns=2 AND state_enum_columns=5 AND known_check_count=0 AND source_indexes=4 AND context_fk_source=2 AND context_fk_target=0) AS source_fingerprint,
      (structure_safe AND data_safe AND calendar_column_total=42 AND event_context_columns=2 AND version_context_columns=0 AND state_varchar_columns=5 AND known_check_count=12 AND source_indexes=0 AND target_indexes=10 AND context_fk_source=0 AND context_fk_target=2 AND table_comments=4) AS target_fingerprint
    FROM safety
),
readiness AS (
    SELECT fingerprints.*, (structure_safe AND data_safe AND NOT source_fingerprint AND NOT target_fingerprint) AS safe_partial
    FROM fingerprints
)
SELECT report_section, result, details
FROM (
  SELECT 1 AS report_order, 'DATABASE_AND_TABLES' AS report_section, IF(database_ok AND required_tables_ok AND calendar_tables_ok,'PASS','FAIL') AS result, CONCAT('database=',database_ok,'; required_tables=',required_tables_ok,'; calendar_tables=',calendar_tables_ok) AS details FROM readiness
  UNION ALL SELECT 2, 'REFERENCE_DATA', IF(data_safe,'PASS','FAIL'), CONCAT('codes=',seed_codes,'; current=',current_count,'; current_active=',current_active,'; semesters=',semester_codes,'; permission=',permission_ok,'; mapping=',role_mapping_ok,'; unauthorized_mappings=',other_mappings) FROM readiness
  UNION ALL SELECT 3, 'EMPTY_EVENT_HISTORY', IF(event_rows=0 AND version_rows=0,'PASS','FAIL'), CONCAT('events=',event_rows,'; versions=',version_rows) FROM readiness
  UNION ALL SELECT 4, 'STRUCTURE_CLASSIFICATION', CASE WHEN source_fingerprint THEN 'REPAIRABLE_SOURCE' WHEN target_fingerprint THEN 'ALREADY_COMPATIBLE' WHEN safe_partial THEN 'SAFE_PARTIAL' ELSE 'CONFLICTING' END, CONCAT('event_context=',event_context_columns,'; version_context=',version_context_columns,'; enum_states=',state_enum_columns,'; varchar_states=',state_varchar_columns,'; checks=',known_check_count,'; unknown_columns=',unknown_columns,'; unknown_fks=',unknown_calendar_fks,'; unknown_indexes=',unknown_indexes) FROM readiness
  UNION ALL SELECT 5, 'OVERALL', IF(source_fingerprint OR target_fingerprint OR safe_partial,'READY','BLOCKED'), 'Run 01_apply.sql only when this row is READY.' FROM readiness
) report
ORDER BY report_order;
